using System;
using System.Collections.Generic;
using System.Linq;
using BTDB.FieldHandler;
using BTDB.ODBLayer;
using Xunit;
using Xunit.Abstractions;

namespace BTDBTest;

/// Runtime regressions of relation implementations generated by BTDB.SourceGenerator.
[Collection("IFieldHandler.UseNoEmitForRelations")]
public class ObjectDbTableSourceGeneratorRegressionTest : ObjectDbTestBase
{
    public ObjectDbTableSourceGeneratorRegressionTest(ITestOutputHelper output) : base(output)
    {
    }

    public class Person
    {
        [PrimaryKey(1)] public ulong TenantId { get; set; }
        [PrimaryKey(2)] public ulong Id { get; set; }
        [SecondaryKey("Name")] public string Name { get; set; } = "";
    }

    public interface IPersonTable : IRelation<Person>
    {
        ICollection<Person> FindById(ulong tenantId);
        IReadOnlyCollection<Person> FindByName(string name);
    }

    // Before the fix IL emitted relations, used for relations without generated code, cast the enumerator, which is
    // no collection, and threw InvalidCastException.
    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void FindByCanReturnCollections(bool noEmit)
    {
        var old = IFieldHandler.UseNoEmitForRelations;
        try
        {
            IFieldHandler.UseNoEmitForRelations = noEmit;
            ObjectDB.ResetAllMetadataCaches();
            FindByReturnsCollections();
        }
        finally
        {
            IFieldHandler.UseNoEmitForRelations = old;
            ObjectDB.ResetAllMetadataCaches();
        }
    }

    void FindByReturnsCollections()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<IPersonTable>();
        table.Upsert(new() { TenantId = 1, Id = 1, Name = "A" });
        table.Upsert(new() { TenantId = 1, Id = 2, Name = "B" });
        table.Upsert(new() { TenantId = 2, Id = 3, Name = "A" });

        var byTenant = table.FindById(1);
        Assert.Equal(2, byTenant.Count);
        Assert.Equal(new ulong[] { 1, 2 }, byTenant.Select(p => p.Id));

        var byName = table.FindByName("A");
        Assert.Equal(2, byName.Count);
        Assert.Equal(new ulong[] { 1, 3 }, byName.Select(p => p.Id));
    }

    public class Price
    {
        [PrimaryKey(1)] public ulong Id { get; set; }
        public decimal? Rate { get; set; }
        public decimal Other { get; set; }
    }

    public interface IPriceTable : IRelation<Price>
    {
        Price? FindByIdOrDefault(ulong id);
        bool UpdateById(ulong id, decimal other);
    }

    // Decimal key fields are refused (BTDB0035), decimal values are stored.
    [Fact]
    public void DecimalValuesAndUpdateByIdValuesWork()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<IPriceTable>();
        table.Upsert(new() { Id = 1, Rate = 0.25m, Other = 10m });
        table.Upsert(new() { Id = 2, Rate = null, Other = 20m });

        Assert.Equal(10m, table.FindByIdOrDefault(1)!.Other);
        Assert.Equal(0.25m, table.FindByIdOrDefault(1)!.Rate);
        Assert.Null(table.FindByIdOrDefault(2)!.Rate);
        Assert.True(table.UpdateById(2, 21.5m));
        Assert.Equal(21.5m, table.FindByIdOrDefault(2)!.Other);
    }

    public enum TagKind : short
    {
        Negative = -3,
        Positive = 7
    }

    public class Tagged
    {
        [PrimaryKey(1)] public ulong Id { get; set; }
        [SecondaryKey("Tags")] public List<int> Tags { get; set; } = [];
        [SecondaryKey("Days")] public HashSet<DateTime> Days { get; set; } = [];
        [SecondaryKey("Kinds")] public List<TagKind> Kinds { get; set; } = [];
    }

    public interface ITaggedTable : IRelation<Tagged>
    {
        IEnumerable<Tagged> ListByTags(List<int> tags);
        IEnumerable<Tagged> ListByDays(HashSet<DateTime> days);
        IEnumerable<Tagged> ListByKinds(List<TagKind> kinds);
    }

    // Before the fix generated lookups threw NotSupportedException for list keys of items other than string and ulong.
    [Fact]
    public void ListKeysOfAnyItemTypeCanBeLookedUp()
    {
        var day = new DateTime(2024, 1, 2, 0, 0, 0, DateTimeKind.Utc);
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<ITaggedTable>();
        table.Upsert(new() { Id = 1, Tags = [1, -2], Days = [day], Kinds = [TagKind.Negative, TagKind.Positive] });
        table.Upsert(new() { Id = 2, Tags = [3], Days = [] });
        Assert.Equal(1ul, Assert.Single(table.ListByTags([1, -2])).Id);
        Assert.Equal(2ul, Assert.Single(table.ListByTags([3])).Id);
        Assert.Empty(table.ListByTags([1]));
        Assert.Equal(1ul, Assert.Single(table.ListByDays([day])).Id);
        Assert.Equal(2ul, Assert.Single(table.ListByDays([])).Id);
        Assert.Equal(1ul, Assert.Single(table.ListByKinds([TagKind.Negative, TagKind.Positive])).Id);
        Assert.Equal(2ul, Assert.Single(table.ListByKinds([])).Id);
    }

    public class TupleKeyed
    {
        [PrimaryKey(1)] public (int Id, TagKind Kind) Key { get; set; }
        public int V { get; set; }
    }

    public interface ITupleKeyedTable : IRelation<TupleKeyed>
    {
        TupleKeyed? FindByIdOrDefault((int Id, TagKind Kind) key);
        IEnumerable<TupleKeyed> ListById(AdvancedEnumeratorParam<(int Id, TagKind Kind)> param);
    }

    // Before the fix generated lookups threw NotSupportedException for tuple keys with enum elements.
    [Fact]
    public void TupleKeysWithEnumElementsCanBeLookedUp()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<ITupleKeyedTable>();
        table.Upsert(new() { Key = (1, TagKind.Negative), V = 10 });
        table.Upsert(new() { Key = (1, TagKind.Positive), V = 20 });
        Assert.Equal(10, table.FindByIdOrDefault((1, TagKind.Negative))!.V);
        Assert.Equal(20, table.FindByIdOrDefault((1, TagKind.Positive))!.V);
        Assert.Null(table.FindByIdOrDefault((2, TagKind.Positive)));
        Assert.Equal(new[] { 20 }, table.ListById(new(EnumerationOrder.Ascending, (1, TagKind.Positive),
            KeyProposition.Included, default, KeyProposition.Ignored)).Select(r => r.V));
    }

    public class TupleValued
    {
        [PrimaryKey(1)] public ulong Id { get; set; }
        public (int A, TagKind Kind) Pair { get; set; }
    }

    public interface ITupleValuedTable : IRelation<TupleValued>
    {
        TupleValued? FindByIdOrDefault(ulong id);
        bool UpdateById(ulong id, (int A, TagKind Kind) pair);
    }

    // Before the fix UpdateById threw NotSupportedException for tuple values with enum elements.
    [Fact]
    public void TupleValuesWithEnumElementsCanBeUpdated()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<ITupleValuedTable>();
        table.Upsert(new() { Id = 1, Pair = (1, TagKind.Positive) });
        Assert.True(table.UpdateById(1, (2, TagKind.Negative)));
        Assert.Equal((2, TagKind.Negative), table.FindByIdOrDefault(1)!.Pair);
    }

    public class Measured
    {
        [PrimaryKey(1)] public ulong Id { get; set; }
        public double D { get; set; }
        public float F { get; set; }
    }

    public interface IMeasuredTable : IRelation<Measured>
    {
        Measured? FindByIdOrDefault(ulong id);
        bool UpdateById(ulong id, double d, float f);
    }

    // Before the fix UpdateById threw NotSupportedException for double and float values.
    [Fact]
    public void FloatingPointValuesCanBeUpdated()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<IMeasuredTable>();
        table.Upsert(new() { Id = 1, D = 1.5, F = 2.5f });
        Assert.True(table.UpdateById(1, -3.25, 4.5f));
        var row = table.FindByIdOrDefault(1)!;
        Assert.Equal(-3.25, row.D);
        Assert.Equal(4.5f, row.F);
    }

    public interface IRedeclaringPersonTable : IRelation<Person>
    {
        new void RemoveAll();
        new (long Inserted, long Updated) UpsertRange(IEnumerable<Person> items);
    }

    [Fact]
    public void RedeclaredRelationDbManipulatorMethodsAreForwarded()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<IRedeclaringPersonTable>();
        var (inserted, updated) = table.UpsertRange([
            new() { TenantId = 1, Id = 1, Name = "A" },
            new() { TenantId = 1, Id = 2, Name = "B" }
        ]);
        Assert.Equal(2, inserted);
        Assert.Equal(0, updated);
        Assert.Equal(2, table.Count);
        table.RemoveAll();
        Assert.Empty(table);
    }

    public class ItemWithComputedKey
    {
        string _name = "";

        [PrimaryKey(1)] public ulong Id { get; set; }

        public string Name
        {
            get => _name;
            set => _name = value;
        }

        [SecondaryKey("NameKey")]
        public string NameKey
        {
            get => _name;
        }

        public int Value { get; set; }
    }

    public interface IItemWithComputedKeyTable : IRelation<ItemWithComputedKey>
    {
        void UpdateById(ulong id, int value);
        ItemWithComputedKey FindByNameKey(string nameKey);
    }

    [Fact]
    public void UpdateByIdSkipsComputedFieldReturningBackingField()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<IItemWithComputedKeyTable>();
        table.Upsert(new() { Id = 1, Name = "first", Value = 1 });
        table.UpdateById(1, 42);
        var item = table.FindByNameKey("first");
        Assert.Equal("first", item.Name);
        Assert.Equal(42, item.Value);
    }

    public class TaggedItem
    {
        [PrimaryKey(1)] public ulong Id { get; set; }
        [SecondaryKey("Tags")] public IList<string> Tags { get; set; } = new List<string>();
    }

    public interface ITaggedItemTable : IRelation<TaggedItem>
    {
        IEnumerable<TaggedItem> ListByTags(IList<string> tags);
    }

    [Fact]
    public void ListBySecondaryKeyAcceptsIListParameter()
    {
        using var tr = _db.StartTransaction();
        var table = tr.GetRelation<ITaggedItemTable>();
        table.Upsert(new() { Id = 1, Tags = ["a", "b"] });
        table.Upsert(new() { Id = 2, Tags = ["c"] });
        Assert.Equal(2ul, Assert.Single(table.ListByTags(["c"])).Id);
    }
}
